struct Writer {FILE* f;explicit Writer(const std::string& path):f(std::fopen(path.c_str(),"wx")){if(!f)throw std::runtime_error("exclusive suspended-tail wire");}void word(u64 x){u8 b[8];store_be32(b,u32(x>>32));store_be32(b+4,u32(x));if(std::fwrite(b,1,8,f)!=8)throw std::runtime_error("suspension wire");}void close(){if(std::fclose(f))throw std::runtime_error("suspension close");}};
